<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$rows=json_decode($_POST['rows']??'[]',true)?:[];if(!$rows)throw new RuntimeException('Add at least one expense.');$db->beginTransaction();$q=$db->prepare('INSERT INTO expenses(category,description,amount) VALUES(?,?,?)');$n=0;foreach($rows as $r){$cat=trim((string)($r['category']??''));$amt=(float)($r['amount']??0);if($cat===''&&$amt<=0)continue;if($cat==='')throw new RuntimeException('Enter a category.');if($amt<=0)throw new RuntimeException('Enter a valid amount for '.$cat.'.');$q->execute([$cat,trim((string)($r['description']??''))?:null,$amt]);audit_log('expense_created','Expense: '.$cat.' · Rs. '.number_format($amt,2));$n++;}$db->commit();header('Location: expenses.php?saved='.$n);exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}$rows=$db->query('SELECT * FROM expenses ORDER BY id DESC LIMIT 200')->fetchAll();$today=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=CURDATE()")->fetchColumn();$month=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetchColumn();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expenses</title><link rel="stylesheet" href="style.css"><style>.bulk{overflow:auto}.bulk table{min-width:650px}.bulk input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.actions{display:flex;gap:10px;margin-top:12px}.remove{border:0;background:none;color:#dc2626;font-size:20px;cursor:pointer}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=e(current_user()['username']??'')?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">FINANCE</div><h1>Expenses</h1><p>Enter several expenses quickly in one screen.</p></div></div><?php if($error):?><div class="error">✕ <?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=e($_GET['saved'])?> expenses recorded.</div><?php endif;?><div class="cards"><div><span>Today's expenses</span><b>Rs. <?=money($today)?></b></div><div><span>This month</span><b>Rs. <?=money($month)?></b></div></div><section class="panel"><h2>➕ Quick Add Expenses</h2><div class="bulk"><table><thead><tr><th>Category *</th><th>Description</th><th>Amount *</th><th></th></tr></thead><tbody id="new"></tbody></table></div><div class="actions"><button type="button" class="btn" id="add">＋ Add Row</button><button type="button" class="btn" id="save">💾 Save All Expenses</button></div></section><section class="panel"><h2>Expense History</h2><div class="bulk"><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><b><?=e($r['category'])?></b></td><td><?=e($r['description']??'—')?></td><td>Rs. <?=money((float)$r['amount'])?></td></tr><?php endforeach;?></table></div></section></main><script>const body=document.getElementById('new');function row(){const tr=document.createElement('tr');tr.innerHTML='<td><input data-k="category" placeholder="Rent, electricity, salary..."></td><td><input data-k="description" placeholder="Optional"></td><td><input data-k="amount" type="number" min="0.01" step="0.01" placeholder="0.00"></td><td><button type="button" class="remove" onclick="this.closest(\'tr\').remove()">×</button></td>';body.appendChild(tr)}document.getElementById('add').onclick=row;document.getElementById('save').onclick=()=>{const rows=[...body.children].map(tr=>{const o={};tr.querySelectorAll('[data-k]').forEach(x=>o[x.dataset.k]=x.value);return o}).filter(x=>x.category.trim()||+x.amount);if(!rows.length)return alert('Add at least one expense.');const f=document.createElement('form');f.method='post';f.innerHTML='<input name="rows">';f.querySelector('[name=rows]').value=JSON.stringify(rows);document.body.appendChild(f);f.submit()};row();row();</script></body></html>